import { Injectable } from "@angular/core";
import { ActivatedRouteSnapshot, convertToParamMap, NavigationExtras, ParamMap, Params } from "@angular/router";
import { BehaviorSubject } from "rxjs";

@Injectable()
export class RouterStub {
	public navigate(_commands: any[], _extras?: NavigationExtras): void {/* empty */ }
}

@Injectable()
export class ActivatedRouteStub {
	// ActivatedRoute.params is Observable
	private subject = new BehaviorSubject(this.testParams);
	public params = this.subject.asObservable();

	// ActivatedRoute.paramMap is Observable
	private testParamMapSubject = new BehaviorSubject<ParamMap>(convertToParamMap({}));
	public paramMap = this.testParamMapSubject.asObservable();

	// ActivatedRoute.data is Observable
	private dataSubject = new BehaviorSubject(this.testData);
	public data = this.dataSubject.asObservable();

	// ActivatedRoute.fragment is Observable
	private fragmentSubject = new BehaviorSubject(this.testFragment);
	public fragment = this.fragmentSubject.asObservable();

	// ActivatedRoute.queryParams is Observable
	private testQueryParamsSubject = new BehaviorSubject<ParamMap>(convertToParamMap({}));
	public queryParamMap = this.testQueryParamsSubject.asObservable();


	// Test parameters
	private _testParams: Params = {};
	private _testParamMap: ParamMap = convertToParamMap(this.testParams);
	get testParams(): Params { return this._testParams; }
	set testParams(params: Params) {
		this._testParams = params;
		this._testParamMap = convertToParamMap(params || {});
		this.subject.next(params);
		this.testParamMapSubject.next(this._testParamMap);
	}

	// Test data
	private _testData = {};
	get testData(): object { return this._testData; }
	set testData(data: object) {
		this._testData = data;
		this.dataSubject.next(data);
	}

	// Test query params
	private _testQueryParams: Params = {};
	private _testQueryParamMap: ParamMap = convertToParamMap(this.testQueryParams);
	get testQueryParams(): Params { return this._testQueryParams; }
	set testQueryParams(testQueryParams: Params) {
		this._testQueryParams = testQueryParams;
		this._testQueryParamMap = convertToParamMap(testQueryParams || {});
		this.testQueryParamsSubject.next(this._testQueryParamMap);
	}

	// Test fragment
	private _testFragment?: string;
	get testFragment(): string | undefined { return this._testFragment; }
	set testFragment(data: string | undefined) {
		this._testFragment = data;
		this.fragmentSubject.next(data);
	}

	// ActivatedRoute.snapshot.params
	get snapshot(): ActivatedRouteSnapshot {
		return {
			params: this.testParams,
			paramMap: convertToParamMap(this.testParams),
			queryParamMap: this._testQueryParamMap,
			data: this.testData
		} as ActivatedRouteSnapshot;
	}
}