import { HttpTestingController } from '@angular/common/http/testing';
import { DebugElement, InputSignal } from '@angular/core';
import { ComponentFixture, TestBed, tick } from '@angular/core/testing';
import { By } from '@angular/platform-browser';
import { MessageService } from 'espd-common/i18n';
import { AbstractEntityDetailComponent, EntityListScaffoldComponent } from 'espd-common/layout/entities';
import { SettingService } from 'espd-common/setting';
import { getProperties } from 'properties-file';

type Matcher = string | jasmine.AsymmetricMatcher<any>;

export const query = (selector: string, relativeTo: ComponentFixture<any> | DebugElement): DebugElement => resolveDebugElement(relativeTo).query(By.css(selector));
export const queryAll = (selector: string, relativeTo: ComponentFixture<any> | DebugElement): DebugElement[] => resolveDebugElement(relativeTo).queryAll(By.css(selector));
export const queryNativeElement = (selector: string, relativeTo: ComponentFixture<any> | DebugElement): HTMLElement => query(selector, relativeTo).nativeElement;
export const resolveDebugElement = (e: ComponentFixture<any> | DebugElement): DebugElement => e instanceof ComponentFixture ? e.debugElement : e;

export const getModalContainer = (): HTMLElement => document.querySelector('modal-content')!;
export const queryModal = (selector: string): HTMLElement | null => getModalContainer()?.querySelector(selector);
export const queryAllModal = (selector: string): NodeListOf<HTMLElement> => getModalContainer()?.querySelectorAll(selector);

export const setInput = (controlName: string, value: string, container: ComponentFixture<any> | DebugElement): void => input(query(`:is(espd-input, espd-text-area)[espdControlName="${controlName}"] :is(input, textarea)`, container), value);
export const setSelect = (controlName: string, value: string, container: ComponentFixture<any> | DebugElement): void => select(query(`espd-select[espdControlName="${controlName}"] select`, container), value);
export const setRadio = (controlName: string, value: string, container: ComponentFixture<any> | DebugElement): void => radio(queryAll(`espd-radio[espdControlName="${controlName}"] input`, container), value);

export const updateInputSignal = <ComponentType, Key extends keyof ComponentType, ValueType extends ComponentType[Key] extends InputSignal<infer U> ? U : never>(fixture: ComponentFixture<ComponentType>, key: Key & string, value: ValueType): void => {
	fixture.componentRef.setInput(key, value);
}

export const expectText = (e: DebugElement | HTMLElement, t: string): void => {
	e = (e instanceof DebugElement ? e.nativeElement : e) as HTMLElement;
	expect(e.innerText.trim()).toBe(t);
};

export const buttonClickEvents = {
	left: { button: 0 },
	right: { button: 2 }
};

export const click = (el: DebugElement | HTMLElement, eventObj?: unknown): void => {
	if (el instanceof HTMLElement) {
		el.click();
	} else if (eventObj) {
		el.triggerEventHandler('click', eventObj);
	} else {
		(el.nativeElement as HTMLElement).click();
	}
};

export const select = (el: DebugElement | HTMLSelectElement, value: any): void => {
	const selectElement: HTMLSelectElement = (el instanceof DebugElement) ? el.nativeElement : el;
	expect(selectElement).not.toBeNull();
	expect(selectElement).toBeInstanceOf(HTMLSelectElement);
	selectElement.value = value;
	selectElement.dispatchEvent(newEvent('change'));
};

export const input = (el: DebugElement | HTMLInputElement | HTMLTextAreaElement, value: any): void => {
	const inputElement: HTMLSelectElement | HTMLTextAreaElement = (el instanceof DebugElement) ? el.nativeElement : el;
	expect(inputElement).not.toBeNull();
	inputElement.value = value;
	inputElement.dispatchEvent(newEvent('input'));
	inputElement.dispatchEvent(newEvent('change'));
	inputElement.blur();
};

export const radio = (el: DebugElement[] | HTMLInputElement[], value: any): void => {
	const inputs = el.map(e => (e instanceof DebugElement) ? e.nativeElement : e) as HTMLInputElement[];
	const selected = inputs.find(e => e.attributes.getNamedItem('ng-reflect-value')?.value === value.toString());

	expect(selected).toBeTruthy();
	if (selected) {
		click(selected);
		selected.dispatchEvent(newEvent('change'));
	}
};

export const newEvent = (eventName: string, bubbles = false, cancelable = false): CustomEvent<any> => {
	return new CustomEvent(eventName, { bubbles, cancelable });
};

export class TestUtils {

	constructor(private fixture: ComponentFixture<any>) { }

	protected static _settings: Record<string, any> = {};
	public set settings(settings: Record<string, any>) {
		TestUtils._settings = settings;
	}

	static mockMessagesAndSettings = (module = 'test'): void => {
		const httpController: HttpTestingController = TestBed.inject(HttpTestingController);
		TestBed.inject(MessageService).init(module);
		const setingService = TestBed.inject(SettingService);
		setingService.init(module);

		httpController.match({ method: 'GET', url: `settings?module=${module}` }).map(req => req.flush(TestUtils._settings));

		const filePath = 'src/main/resources/i18n/messages_en_US.properties';
		const request = new XMLHttpRequest();
		request.open('GET', 'base/' + filePath, false);
		request.onload = _r => {
			const messages = getProperties(request.responseText);
			httpController.match({ method: 'GET', url: `messages?module=${module}` }).map(req => req.flush(messages));
		};
		request.send(null);
	}

	public query = (selector: string, relativeTo?: DebugElement): DebugElement => query(selector, relativeTo ?? this.fixture);
	public queryAll = (selector: string, relativeTo?: DebugElement): DebugElement[] => queryAll(selector, relativeTo ?? this.fixture);
	public queryNativeElement = (selector: string, relativeTo?: DebugElement): HTMLElement => queryNativeElement(selector, relativeTo ?? this.fixture);

	public setInput = (controlName: string, value: string): void => setInput(controlName, value, this.fixture);
	public setSelect = (controlName: string, value: string): void => setSelect(controlName, value, this.fixture);
	public setRadio = (controlName: string, value: string): void => setRadio(controlName, value, this.fixture);

	public updateInputSignal = <ComponentType, Key extends keyof ComponentType, ValueType extends ComponentType[Key] extends InputSignal<infer U> ? U : never>(key: Key & string, value: ValueType): void => {
		this.fixture.componentRef.setInput(key, value);
	}

	public openTableDropdown = (row = 0): void => {
		const dropdownButton = query(`table tbody tr:nth-child(${row + 1}) td espd-table-action-cell .dropdown button`, this.fixture);
		click(dropdownButton);
		tick(1000);
		this.fixture.detectChanges();
	};

	public clickTableAction = (index = 0, row = 0): DebugElement => {
		this.openTableDropdown(row);
		const action = queryAll(`table tbody tr:nth-child(${row + 1}) td div.dropdown-menu .dropdown-item`, this.fixture)[index];
		if (action) {
			click(action);
			tick(500); // fade duration is 150ms, completion is 300ms
			this.fixture.detectChanges();
		}
		return action;
	};

	public expectTableData = (data: Matcher[][], table?: DebugElement): void => {
		const rows = queryAll('tbody tr', table ?? this.query('table'));
		expect(rows.length).toBe(data.length);
		rows.forEach((row, rowIndex) => {
			const cols = queryAll('td:first-child, td .value', row);
			const colData = data[rowIndex];
			expect(cols.length).toBe(colData.length);
			colData.forEach((expected, colIndex) => {
				const value = cols[colIndex].nativeElement.textContent.trim()
				expect(value).toEqual(expected);
			});
		});
	};

	public finishListScaffoldInitialization = (): void => {
		const component = this.fixture.componentInstance;
		this.fixture.detectChanges();
		tick();
		(component.listScaffold as EntityListScaffoldComponent).doneLoading();
		this.fixture.detectChanges();
	}

	public saveScaffoldForm = (): void => {
		const button = queryNativeElement('form div.button-group > espd-button button[type="submit"', this.fixture);
		click(button);
	}

	public expectScaffoldFormSetup = (fields: string[]): void => {
		const component: AbstractEntityDetailComponent<any, any, any> = this.fixture.componentInstance;
		expect(component.form).toBeTruthy();
		const formValue = component.form.getRawValue() as object;
		expect(Object.keys(formValue)).toEqual(jasmine.arrayWithExactContents(fields));
	};
}